def solution(*args, **kwargs):
    import sys

    # Support both direct argument call (for tests) and stdin input
    if args:
        x = int(args[0])
    else:
        data = sys.stdin.read().strip()
        if not data:
            return
        x = int(data)

    x_str = str(x)
    n = len(x_str)

    # Helper: sum of digits
    def digit_sum(num):
        s = 0
        while num:
            s += num % 10
            num //=10
        return s

    # Start with x itself
    best = x
    best_sum = digit_sum(x)

    # Try: keep prefix, decrease one digit by 1, make rest 9s
    for i in range(n):
        d = int(x_str[i])
        if d == 0:
            continue
        cand_str = x_str[:i] + str(d - 1) + '9' * (n - i - 1)
        if cand_str[0] == '0':
            continue
        cand = int(cand_str)
        if 0 < cand <= x:
            sd = digit_sum(cand)
            if sd < best_sum or (sd == best_sum and cand < best):
                best_sum = sd
                best = cand

    # Also consider numbers of form 99...9 with fewer digits
    for length in range(1, n):
        cand = int('9' * length)
        if cand <= x:
            sd = 9 * length
            if sd < best_sum or (sd == best_sum and cand < best):
                best_sum = sd
                best = cand

    # If called as function, return value; if via stdin, print
    if args:
        return best
    else:
        print(best)

